// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access, uint256 tokenId) public {
        tokenId = bound(tokenId, 0, 100);
        vm.assume(admin != address(0));

        // Set up admin access
        c.adjustAdminAccess(admin, access);

        // The property: balanceOf(address(0), any tokenId) should always revert
        vm.expectRevert("ERC1155: address zero is not a valid owner");
        c.balanceOf(address(0), tokenId);
        assertTrue(true);
    }
}

