pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 tokenId, bool access) public {
        // Bound tokenId to prevent array out-of-bounds
        uint256 maxTokens = c.uniqueTokensOutstanding();
        tokenId = bound(tokenId, 0, maxTokens > 0 ? maxTokens - 1 : 0);

        // Ensure we have at least one token created to test
        if (maxTokens == 0) {
            vm.assume(false); // skip if no tokens
        }

        // Call adjustAdminAccess to potentially change state
        vm.assume(account != address(0)); // non-zero address to trigger bug
        c.adjustAdminAccess(account, access);

        // The property: balanceOf should return 0 for any account that never received tokens
        uint256 balance = c.balanceOf(account, tokenId);
        assertTrue(balance == 0);
    }
}

