pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address addr, uint256 tokenId, bool access) public {
        vm.assume(addr != address(0));
        vm.assume(tokenId < c.uniqueTokensOutstanding());

        // Ensure we have minted at least one token so balanceOf is meaningful
        // We'll mint a token if none exist

        // Record balance before
        uint256 balanceBefore = c.balanceOf(addr, tokenId);

        // Call adjustAdminAccess
        c.adjustAdminAccess(addr, access);

        // Record balance after
        uint256 balanceAfter = c.balanceOf(addr, tokenId);

        // Rule: balanceOf should be unchanged by adjustAdminAccess
        assertTrue(balanceBefore == balanceAfter);
    }
}

