pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id) public {
        vm.assume(account != address(0));

        // We need a token to exist for balanceOf to not revert on invalid id
        // But balanceOf only reverts for address(0), so we can call with any id
        // Just ensure the call doesn't revert on account zero

        uint256[] memory accounts = new uint256[](1);
        address[] memory addrs = new address[](1);
        addrs[0] = account;
        accounts[0] = id;

        uint256[] memory balances = c.balanceOfBatch(addrs, accounts);
        uint256 singleBalance = c.balanceOf(account, id);

        assertTrue(balances[0] == singleBalance);
    }
}

