import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        // Bound input lengths to ensure consistency and avoid out-of-gas
        vm.assume(accounts.length == ids.length && accounts.length <= 5);

        // Cast to address[] calldata for balanceOfBatch
        address[] memory memAccounts = accounts;
        uint256[] memory memIds = ids;
        uint256[] memory batchBalances = c.balanceOfBatch(memAccounts, memIds);

        // Verify that balanceOfBatch returns the same as individual balanceOf calls
        for (uint256 i = 0; i < accounts.length; i++) {
            uint256 individualBalance = c.balanceOf(accounts[i], ids[i]);
            assertTrue(batchBalances[i] == individualBalance);
        }
    }
}

