pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        // Bound inputs to prevent out-of-gas / unrealistic arrays
        vm.assume(accounts.length == ids.length && accounts.length <= 10);
        for (uint256 i = 0; i < accounts.length; i++) {
            vm.assume(accounts[i] != address(0));
        }

        // Compute expected sums: for each id, sum balanceOf across all accounts
        uint256[] memory expected = new uint256[](ids.length);
        for (uint256 i = 0; i < accounts.length; i++) {
            // We need to call balanceOf for each (account, id) pair
            // Since the contract may revert for address(0) we already excluded that
            expected[i] = c.balanceOf(accounts[i], ids[i]);
        }

        // Get batch balances
        uint256[] memory batch = c.balanceOfBatch(accounts, ids);

        // Verify each element matches
        bool allMatch = true;
        for (uint256 i = 0; i < accounts.length; i++) {
            if (batch[i] != expected[i]) {
                allMatch = false;
            }
        }
        assertTrue(allMatch);
    }
}

